// Shared failure handler for every step of "YouTube Publish Project".
// Classifies the provider error (terminal vs. retryable -- node-level
// retryOnFail already handled 429/5xx by the time an error reaches
// here, so anything arriving here is either a genuinely terminal
// provider error (401/403 forbidden/403 quota) or a non-provider
// validation/preflight failure) and records it against the
// published_videos row -- but only once that row exists (get_or_create_publication_record
// runs partway through the pipeline; earlier steps have no row to
// attach a failure to, and the generic errors-table record from
// fail-workflow-run.json already covers those). See
// docs/architecture/youtube-publication-pipeline.md#retry-and-failure-handling.
const b = $input.first().json;
const TERMINAL_CODES = new Set(['YOUTUBE_AUTH_FAILED', 'YOUTUBE_QUOTA_EXCEEDED', 'YOUTUBE_CREDENTIAL_NOT_CONFIGURED', 'YOUTUBE_PREFLIGHT_FAILED', 'YOUTUBE_SCHEDULE_INVALID']);
const retryable = b.retryable !== undefined && b.retryable !== null ? b.retryable : !TERMINAL_CODES.has(b.error_code);
return [{ json: {
  channel_id: b.channel_id, published_video_id: b.published_video_id ?? null, workflow_run_id: b.workflow_run_id,
  error_code: b.error_code, message: b.message, sanitized_details: b.sanitized_details ?? {}, retryable,
} }];
